var QUESTOES_TRANSITIVIDADE = [{"id":300,"enunciado":"Analise a frase a seguir, extraída do texto 2. “Alunos que permanecem por uma aula inteira fazendo brincadeiras inadequadas, conversam entre si sobre assuntos não pertinentes ao ambiente acadêmico, tecem comentários depreciativos sobre professores ou colegas e fazem piadas de duplo sentido.” Assinale a alternativa correta sobre essa frase.","opcoes":["Na frase não ocorre pronome.","A conjunção integrante “que” inicia uma oração subordinada substantiva completiva nominal.","O verbo “conversam” é transitivo indireto e seu complemento é “sobre assuntos não pertinentes ao ambiente acadêmico”.","O termo “por uma aula inteira” exerce a função de objeto direto do verbo “permanecem”.","Nos vocábulos “aula” e “inadequadas” ocorrem, respectivamente, dois ditongos decrescentes."],"correta":2,"explicacao":"Gabarito: <strong>O verbo “conversam” é transitivo indireto e seu complemento é “sobre assuntos não pertinentes ao ambiente acadêmico”.</strong>.","banca":"FEPESE","ano":2022,"temas_relacionados":["transitividade","ditongos"]},{"id":2804,"enunciado":"No trecho Apesar da importância da descoberta, os autores não afirmam que o níquel esteja ligado à presença de vida, a ocorrência da crase se justifica gramaticalmente porque:","opcoes":["A palavra antecedente é um verbo transitivo direto que exige o acompanhamento de preposição pura.","O termo feminino subsequente repele o uso de artigos definidos, restando apenas a preposição de tempo e lugar.","O adjetivo antecedente exige a preposição a, que se contrai com o artigo feminino definido exigido pelo substantivo subsequente.","A locução conjuntiva de oposição impõe o acento grave em qualquer palavra feminina que seja posicionada no final do período."],"correta":2,"explicacao":"Gabarito: <strong>O adjetivo antecedente exige a preposição a, que se contrai com o artigo feminino definido exigido pelo substantivo subsequente.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["transitividade","crase"]},{"id":3141,"enunciado":"Treviso consolidou-se como exemplo de harmonia entre tradição e inovação. Em se tratando de colocação pronominal, é correto afirmar que:","opcoes":["o pronome \"se\" poderia anteceder o verbo, formando próclise, uma vez que o sujeito \"Treviso\" funciona como elemento atrativo que exige a colocação do pronome antes do verbo.","o pronome \"se\" poderia ser suprimido sem alterar a estrutura da frase, já que o verbo \"consolidar\" mantém sentido completo mesmo sem o uso do pronome.","o pronome \"se\" está corretamente posposto ao verbo, formando ênclise, pois o verbo \"consolidar-se\" admite essa colocação quando não há palavra atrativa antes dele.","o pronome \"se\" tem função de objeto direto do verbo \"consolidar\", pois recebe a ação verbal, estabelecendo relação transitiva direta entre o verbo e o sujeito."],"correta":2,"explicacao":"Gabarito: <strong>o pronome \"se\" está corretamente posposto ao verbo, formando ênclise, pois o verbo \"consolidar-se\" admite essa colocação quando não há palavra atrativa antes dele.</strong>.","banca":"UNIVALI","ano":2025,"temas_relacionados":["transitividade"]},{"id":3286,"enunciado":"Como o uso do \"a gente\", comentado no trecho: \"Usar 'a gente' no lugar de 'nós' (...) é um dos sinais da suposta deterioração da língua...\" (linhas 09-10), constitui também sinal da suposta deterioração da língua empregar:","opcoes":["a próclise em início de frase, como em \"me refiro ao estrago...\" (linha 04).","o pronome \"esses\" (linha 10) no lugar de \"estes\".","\"porque\", junto e sem acento em frase interrogativa, como ocorre na (linha 13).","a preposição \"por\" com verbo transitivo direto, como em \"arranhando por ouvidos e almas\" (linhas 21-22)."],"correta":0,"explicacao":"Gabarito: <strong>a próclise em início de frase, como em \"me refiro ao estrago...\" (linha 04).</strong>.","banca":"FCPC","ano":2025,"temas_relacionados":["transitividade"]},{"id":3500,"enunciado":"A compreensão da gramática é fundamental para uma comunicação eficaz e precisa. Nesse contexto, assinale a alternativa que apresenta uma informação CORRETA:","opcoes":["O \"i\" e \"u\" átonos recebem acento quando formam hiato com a vogal anterior; estão sozinhos na sílaba (ou acompanhados apenas de \"s\"); e não sejam seguidos por \"nh\". Exemplos: saúde, saída, egoísmo.","Quando o verbo principal está no PARTICÍPIO, o pronome átono não pode ser enclítico a ele, portanto, o pronome deverá ser PROCLÍTICO ou ENCLÍTICO ao verbo auxiliar.","A partícula apassivadora \"se\" é usada quando o sujeito aparece depois do verbo, e o verbo concorda sempre com o sujeito, como se pode ver em: \"Precisam-se de pedreiros com experiência em acabamento\".","Na frase \"Entreguei-lhe o pedido e fui saindo devagar\", a forma verbal ENTREGUEI é classificada, no contexto em que foi empregada, quanto à sua transitividade (Regência Verbal) como sendo transitiva direta."],"correta":1,"explicacao":"Gabarito: <strong>Quando o verbo principal está no PARTICÍPIO, o pronome átono não pode ser enclítico a ele, portanto, o pronome deverá ser PROCLÍTICO ou ENCLÍTICO ao verbo auxiliar.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["transitividade"]},{"id":3610,"enunciado":"Com base no Texto 1 \"Quem é o 'bom professor'?\", analise as afirmativas a seguir: I. No excerto: \"..Em dado momento, a dinâmica do curso levou-nos a indagar sobre a figura do bom professor\", fez-se a opção pela ênclise do pronome oblíquo destacado “nos”, uma vez que não há palavra que o atraia, obrigando-o a ocupar a posição antes do verbo; \"indagar\" está sendo empregado como verbo transitivo indireto, neste contexto. Il. No excerto: \"...Mantive comigo o teor dessa frase, mas ofereci às participantes o mote”, o pronome oblíquo tônico comigo\" exerce a função sintática de complemento verbal direto e o emprego da crase '\"às” justifica-se, pois o verbo 'oferecer' é bitransitivo com preposição 'a' que se funde com o artigo 'a' admitido pela palavra 'participantes”. Marque a alternativa CORRETA:","opcoes":["As duas afirmativas são verdadeiras.","A afirmativa I é verdadeira, e a II é falsa.","A afirmativa II é verdadeira, e a I é falsa.","As duas afirmativas são falsas."],"correta":1,"explicacao":"Gabarito: <strong>A afirmativa I é verdadeira, e a II é falsa.</strong>.","banca":"ADM&TEC","ano":2023,"temas_relacionados":["transitividade","crase"]},{"id":3675,"enunciado":"Na segunda fala de Hagar, sobre o verbo “lembrar”, é CORRETO afirmar que foi usado, de acordo com a norma, como","opcoes":["pronominal e transitivo indireto.","pronominal e transitivo direto.","não pronominal e intransitivo.","transitivo direto apassivado.","não pronominal e apassivado."],"correta":0,"explicacao":"Gabarito: <strong>pronominal e transitivo indireto.</strong>.","banca":"COTEC","ano":2023,"temas_relacionados":["transitividade"]},{"id":3687,"enunciado":"Analise o excerto indicado a seguir, quanto à construção do período e o uso de pronomes. Observe as proposições: Desmurget alerta que, para que as regras tenham sucesso, é importante envolver as crianças na construção dessas restrições, porque quando entendem que o objetivo não é puni-las nem frustrá-las, tendem a seguir as regras com maior tranquilidade. I. Os pronomes destacados estão na forma enclítica. II. Os pronomes destacados retomam o vocábulo crianças. III. Os pronomes destacados poderiam ser escritos na forma proclítica, e não provocariam incorreções gramaticais. IV. Os pronomes destacados também exercem função de objeto direto, visto que complementam o sentido de verbos transitivos direto ( punir/frustrar). V. Ao substituir o termo referenciado por um pronome oblíquo, o autor utilizou um recurso anafórico no processo de construção deste período. Está correto o que se afirma em:","opcoes":["I, II e V, apenas.","II, III e IV, apenas.","I, III, IV e V, apenas.","I, II, III, IV e V."],"correta":3,"explicacao":"Gabarito: <strong>I, II, III, IV e V.</strong>.","banca":"Unoesc","ano":2023,"temas_relacionados":["transitividade"]},{"id":3799,"enunciado":"Identifique abaixo as afirmativas verdadeiras ( V ) e as falsas ( F ). ( ) Na frase: “Ela não se move em relação à Terra”, temos um exemplo de verbo intransitivo. ( ) Está correto o uso da crase em: “Voltei à pensar no geocentrismo depois dessa leitura”. ( ) A posição do pronome oblíquo em relação ao verbo segue a prescrição da norma-padrão em: “Antes que saia, me diga o que fazer quando olhar novamente o firmamento estrelado”. ( ) Na frase: “Embora esteja com certa desconfiança, irei ao seu encontro”, há uma relação de concessão entre as frases. ( ) Na frase: “Essa lei passará a vigorar no ano seguinte àquele em que foi sancionada”, o uso da crase está correto. Assinale a alternativa que indica a sequência correta, de cima para baixo.","opcoes":["V • V • V • F • F","V • V • F • F • V","V • F • F • V • V","F • V • V • F • F","F • F • V • V • V"],"correta":2,"explicacao":"Gabarito: <strong>V • F • F • V • V</strong>.","banca":"FEPESE","ano":2023,"temas_relacionados":["transitividade","crase"]},{"id":4100,"enunciado":"Assinale a opção incorreta conforme a classe morfológica descrita:","opcoes":["Essa iniciativa está totalmente alinhada... 7§ - advérbio de modo.","... e as mais recentes tecnologias... 8§ - adjetivo simples.","O projeto busca estimular... 6§ - substantivo simples.","...o currículo é enriquecido... 11§ - verbo intransitivo.","O professor coordenador Lucas Mateus... 12§ - substantivo próprio."],"correta":3,"explicacao":"Gabarito: <strong>...o currículo é enriquecido... 11§ - verbo intransitivo.</strong>.","banca":"IVIN","ano":2025,"temas_relacionados":["transitividade"]},{"id":4129,"enunciado":"Considerando o período composto retirado do texto “Cabe aos cientistas investigar os fatores preponderantes para a queda nos casos”, assinale a alternativa INCORRETA.","opcoes":["A segunda oração é subordinada substantiva.","O verbo da primeira oração é transitivo indireto.","O sujeito do período é “aos cientistas”.","Há inversão no período, com o predicado vindo antes do sujeito."],"correta":2,"explicacao":"Gabarito: <strong>O sujeito do período é “aos cientistas”.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["transitividade"]},{"id":4130,"enunciado":"\"Segundo uma pesquisa nacional conduzida pela Fundação Carlos Chagas (FCC) em parceria com o Ministério da Educação (MEC), 71,7% dos gestores escolares afirmam ter dificuldades para dialogar sobre o enfrentamento às violências.\"Considerando a regência verbal, marque com V as afirmativas verdadeiras ou com F as falsas.(__)O verbo 'dialogar' classifica-se como transitivo indireto, uma vez que seu complemento é obrigatoriamente introduzido por preposição. No trecho em análise, o verbo apresenta dois complementos indiretos explícitos, 'sobre o enfrentamento' e 'às violências', sendo o segundo introduzido pela preposição 'a' contraída com o artigo definido feminino plural 'as', o que justifica o emprego da crase em 'às violências'. (__)O verbo 'dialogar' atua como transitivo indireto, uma vez que seu complemento é obrigatoriamente introduzido por preposição, sem a qual o sentido do verbo permanece incompleto. Em outros contextos, o mesmo verbo admite a preposição 'com' para introduzir o complemento que indica o interlocutor, configurando, em ambos os casos, construções igualmente corretas do ponto de vista da norma culta, com distinção semântica determinada pela escolha da preposição.(__)O verbo 'afirmar' classifica-se como transitivo direto, exigindo complemento sem preposição. No período em análise, o objeto direto é representado por uma oração reduzida de infinitivo, 'ter dificuldades para dialogar sobre o enfrentamento às violências', denominada oração subordinada substantiva objetiva direta reduzida de infinitivo, que poderia ser substituída, sem prejuízo gramatical, pela forma desenvolvida 'que têm dificuldades para dialogar sobre o enfrentamento às violências'.Assinale a alternativa que apresenta a sequência correta dos itens acima, de cima para baixo.","opcoes":["F, V, V.","V, F, V.","V, F, F.","F, V, F."],"correta":0,"explicacao":"Gabarito: <strong>F, V, V.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["transitividade","crase"]},{"id":4131,"enunciado":"\"Segundo uma pesquisa nacional conduzida pela Fundação Carlos Chagas (FCC) em parceria com o Ministério da Educação (MEC), 71,7% dos gestores escolares afirmam ter dificuldades para dialogar sobre o enfrentamento às violências.\"Considerando a regência verbal, marque com V as afirmativas verdadeiras ou com F as falsas. (__) O verbo 'dialogar' classifica-se como transitivo indireto, uma vez que seu complemento é obrigatoriamente introduzido por preposição. No trecho em análise, o verbo apresenta dois complementos indiretos explícitos, 'sobre o enfrentamento' e 'às violências', sendo o segundo introduzido pela preposição 'a' contraída com o artigo definido feminino plural 'as', o que justifica o emprego da crase em 'às violências'.(__) O verbo 'dialogar' atua como transitivo indireto, uma vez que seu complemento é obrigatoriamente introduzido por preposição, sem a qual o sentido do verbo permanece incompleto. Em outros contextos, o mesmo verbo admite a preposição 'com' para introduzir o complemento que indica o interlocutor, configurando, em ambos os casos, construções igualmente corretas do ponto de vista da norma culta, com distinção semântica determinada pela escolha da preposição.(__) O verbo 'afirmar' classifica-se como transitivo direto, exigindo complemento sem preposição. No período em análise, o objeto direto é representado por uma oração reduzida de infinitivo, 'ter dificuldades para dialogar sobre o enfrentamento às violências', denominada oração subordinada substantiva objetiva direta reduzida de infinitivo, que poderia ser substituída, sem prejuízo gramatical, pela forma desenvolvida 'que têm dificuldades para dialogar sobre o enfrentamento às violências'.Assinale a alternativa que apresenta a sequência correta dos itens acima, de cima para baixo.","opcoes":["V, F, F.","V, F, V.","F, V, F.","F, V, V."],"correta":3,"explicacao":"Gabarito: <strong>F, V, V.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["transitividade","crase"]},{"id":4132,"enunciado":"\"Além do tombamento da comunidade em Campo Grande, há outros 23 quilombos na fase de documentação em que os moradores participam apontando o que deveria ser tombado. Mais 15 casos estão em análise pelos especialistas do Instituto Nacional de Colonização e Reforma Agrária (Incra).\" Considerando a análise sintática, analise as asserções a seguir: I. A expressão 'pelos especialistas do Instituto Nacional de Colonização e Reforma Agrária' exerce a função de agente da passiva, termo integrante da oração que indica os responsáveis pela realização da análise mencionada no trecho, atribuindo ao procedimento um caráter institucional e técnico ao associá-lo à atuação de profissionais vinculados ao órgão competente. II. A oração 'o que deveria ser tombado' é uma oração subordinada substantiva objetiva direta do verbo 'apontar', exercendo a função de objeto direto sem preposição e evidenciando, nesse contexto, a transitividade direta do verbo. III. O verbo 'haver' é impessoal, pertencendo a uma oração sem sujeito e, portanto, não admite sujeito, embora exija complemento verbal. Já a oração 'em que os moradores participam apontando o que deveria ser tombado' é uma oração subordinada adjetiva restritiva que retoma anaforicamente o sintagma 'fase de documentação', especificando a etapa em que ocorre a participação dos moradores, sem que haja ambiguidade referencial quanto ao antecedente do pronome relativo. Assinale a alternativa que apresenta as proposições corretas.","opcoes":["I, II e III.","I e II, apenas.","II, apenas.","III, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["transitividade"]},{"id":4206,"enunciado":"No trecho \"Quando acordou, minha filha me contou que tinha visto a lua mais bonita do mundo\", o verbo \"contar\" é empregado com um uso típico da norma-padrão. Considerando a estrutura da oração, a transitividade verbal e a função sintática dos termos pode-se afirmar que esse verbo é:","opcoes":["transitivo direto e indireto, exigindo dois complementos: um objeto indireto (\"me\") e um objeto direto (\"que tinha visto a lua mais bonita do mundo\").","transitivo indireto e exige apenas um complemento com preposição \"a\", como em \"contou a mim\".","intransitivo, pois o sentido de relatar já está completo com o uso do pronome \"me\".","transitivo direto, e o pronome \"me\" atua como objeto direto, substituindo a oração subordinada."],"correta":0,"explicacao":"Gabarito: <strong>transitivo direto e indireto, exigindo dois complementos: um objeto indireto (\"me\") e um objeto direto (\"que tinha visto a lua mais bonita do mundo\").</strong>.","banca":"ACCESS","ano":2025,"temas_relacionados":["transitividade"]},{"id":4238,"enunciado":"Com base no texto, julgue o item a seguir. No trecho “O Sindicato dos Médicos de Sergipe (Sindimed) disse, também por meio de nota, que é contra qualquer tipo de violência e que é extremamente importante que o estado venha a dar toda assistência à usuária.”, a oração “que o estado venha a dar toda assistência à usuária” é subordinada substantiva objetiva o direta, complementando sentido de um verbo transitivo direto, da oração principal.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["transitividade"]},{"id":4376,"enunciado":"As proposições listadas na sequência versam sobre os elementos linguísticos e seu papel na organização sintática e textual no excerto I. Analise-as e indique a única explicação que NÃO tem correspondência com o uso feito no texto","opcoes":["A elipse do sujeito a partir do segundo ao quarto período é um dos recursos de coesão de que o autor se utiliza para evitar repetição, o que torna a leitura mais fluente.","O texto apresenta 5 períodos justapostos, sinalizados por ponto; o terceiro período é formado pelo processo de coordenação (neste, há 4 estruturas coordenadas); e o último é formado por subordinação.","O texto descreve as habilidades das abelhas, sendo a última habilidade posta em destaque por meio da partícula ATÉ, que, no texto, indica não uma simples inclusão, mas gradação/limite.","Do ponto de vista da flexão modo-temporal, os verbos são usados predominantemente no presente do indicativo; apenas o verbo ver se apresenta no subjuntivo.","Quanto à transitividade, há verbos transitivos diretos, indiretos, predicativos, pronominais e há os que são usados no sentido intransitivo/absoluto, como contar e brincar."],"correta":3,"explicacao":"Gabarito: <strong>Do ponto de vista da flexão modo-temporal, os verbos são usados predominantemente no presente do indicativo; apenas o verbo ver se apresenta no subjuntivo.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["transitividade"]},{"id":4543,"enunciado":"Releia o trecho a seguir.“O levantamento do Datafolha revela que, entre os desempregados, 38% disseram que não tiveram comida suficiente.”No período composto transcrito do texto, os verbos destacados são","opcoes":["complementados por orações que funcionam como objeto direto.","complementados por orações que funcionam como objeto indireto.","intransitivos e, portanto, não pedem complemento verbal.","seguidos de orações que funcionam como predicativos."],"correta":0,"explicacao":"Gabarito: <strong>complementados por orações que funcionam como objeto direto.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2023,"temas_relacionados":["transitividade"]},{"id":4551,"enunciado":"Observe os períodos a seguir e, a partir das afirmativas, assinale a alternativa correta (6º§): “Voltarelli informa que é proibido segurar ou mexer no aparelho celular enquanto dirigimos”.I. A partícula “que” é uma conjunção integrante, pois introduz uma oração subordinada substantiva.II. “informa” é verbo transitivo direto, portanto, a oração que lhe segue é uma oração subordinada substantiva objetiva direta.III. “é proibido segurar ou mexer no aparelho celular” tem o sujeito inexistente “nós”, recuperado pelo verbo “mexer”.","opcoes":["Apenas a afirmativa I está correta.","Apenas a afirmativa II está correta.","Apenas a afirmativa III está correta.","Apenas as afirmativas I e II estão corretas.","Apenas as afirmativas II e III estão corretas."],"correta":3,"explicacao":"Gabarito: <strong>Apenas as afirmativas I e II estão corretas.</strong>.","banca":"IBFC","ano":2023,"temas_relacionados":["transitividade"]},{"id":5587,"enunciado":"Em “[...] as crianças surdas que chegavam àquelas comunidades aprendiam o sistema [...]”, o acento grave na palavra “àquelas” se justifica, CORRETAMENTE, por:","opcoes":["Haver um verbo transitivo indireto na oração.","Haver uma junção entre artigo feminino e pronome demonstrativo.","Haver uma crase exigida pelo verbo “chegar”","Haver uma contração da preposição “a” com o “a” inicial do demonstrativo feminino plural “aquelas”."],"correta":3,"explicacao":"Gabarito: <strong>Haver uma contração da preposição “a” com o “a” inicial do demonstrativo feminino plural “aquelas”.</strong>.","banca":"CONSULPAM","ano":2023,"temas_relacionados":["transitividade"]},{"id":5681,"enunciado":"Considerando o aviso, dadas as afirmativas acerca dos aspectos sintáticos e gramaticais, I. O adjetivo “permitida” empregado em “Não é entrada...”, comparado ao verbo permitir, possui transitividade indireta; por isso, o uso da preposição “a”. II. Há, no aviso, mais de um desvio da norma culta. Dentre eles, um exemplo de paronímia. III. O uso do vocábulo “desta” em “desta regra resultará em multa” se deve ao fato de o referente já ter sido citado anteriormente. IV. Há, no contexto em questão, a correta indicação do fenômeno da crase, que consiste em evidenciar a junção da preposição “a” mais o artigo definido “a”. verifica-se que está/ão correta/s","opcoes":["II, apenas.","I e III, apenas.","III e IV, apenas.","I, II e IV, apenas.","I, II, III e IV."],"correta":0,"explicacao":"Gabarito: <strong>II, apenas.</strong>.","banca":"FUNDEPES","ano":2023,"temas_relacionados":["transitividade","crase"]},{"id":5769,"enunciado":"Leia a frase: Falta-lhe um cérebro. Assinale a opção CORRETA.","opcoes":["um cérebro: artigo e substantivo com função de predicado.","Falta-lhe: predicado verbo-nominal.","Falta: verbo transitivo direto.","cérebro: adjetivo substantivado com função de sujeito.","lhe: pronome oblíquo com função sintática de objeto indireto."],"correta":4,"explicacao":"Gabarito: <strong>lhe: pronome oblíquo com função sintática de objeto indireto.</strong>.","banca":"AMAUC","ano":2022,"temas_relacionados":["transitividade"]},{"id":5869,"enunciado":"Sobre as funções morfológicas e sintáticas presentes nas falas da Charge, assinale a alternativa incorreta:","opcoes":["A palavra “Meu” (primeira fala) exerce função morfológica de pronome possessivo.","O verbo “esperava” (segunda fala) possui transitividade direta e indireta.","O termo “que” (segunda fala) exerce função morfológica de pronome interrogativo.","A palavra “não” exerce função morfológica de advérbio de negação.","Na Charge há a presente de artigo indefinido."],"correta":1,"explicacao":"Gabarito: <strong>O verbo “esperava” (segunda fala) possui transitividade direta e indireta.</strong>.","banca":"AMAUC","ano":2021,"temas_relacionados":["transitividade"]},{"id":6138,"enunciado":"Em relação à ocorrência da palavra a nos enunciados seguintes, avalie as afirmações que se seguem: I. Um Secretário de Instrución Pública falava a um grupo de alunos em uma escola e os incentivava a “ler”. II. Depois disso é que surgiu a piada narrada no primeiro parágrafo, uma montagem. III. Observe-se que o fenômeno ocorre nos dois casos, o que favorece a tese dos sociolinguistas.","opcoes":["A palavra a classifica-se, respectivamente, como: artigo – preposição – artigo.","Em todas as três ocorrências, a palavra a pertence à mesma classe gramatical.","Somente em uma ocorrência a palavra a encabeça o complemento de um verbo transitivo direto.","Somente uma ocorrência registra um caso da preposição a."],"correta":3,"explicacao":"Gabarito: <strong>Somente uma ocorrência registra um caso da preposição a.</strong>.","banca":"FUMARC","ano":2018,"temas_relacionados":["transitividade"]},{"id":6196,"enunciado":"Escreva V ou F, conforme sejam verdadeiras ou falsas as afirmações sobre os recursos linguísticos empregados no texto. ( ) “Muitas adolescentes ficam grávidas porque querem...” (linha 2). A autora, ao empregar “querem”, no presente do indicativo, confirma a sua certeza diante do fato expresso pelo verbo. ( ) “...os adolescentes a refletirem sobre as mudanças resultantes de uma gravidez na adolescência (linha 17). O uso do artigo “as” revela uma referência imprecisa ao substantivo “mudanças”. ( ) “Invariavelmente, descobrimos que o motivo que levou à gravidez está ligado à falta de perspectiva...” (linha 09). O sujeito sintático do verbo destacado é classificado como indeterminado. ( ) “apenas uma pequena fração engravida por acidente.” (linha 3). O verbo destacado é classificado como intransitivo. A sequência CORRETA é","opcoes":["F, V, F, V","V, V. F, F","V, F, F, V","V, F, F, F","F, F, V, V"],"correta":2,"explicacao":"Gabarito: <strong>V, F, F, V</strong>.","banca":"CPCON","ano":2017,"temas_relacionados":["transitividade"]},{"id":6198,"enunciado":"Escreva Vou F, conforme sejam verdadeiras ou falsas as afirmações sobre os recursos linguísticos empregados no texto. ( ) “Muitas adolescentes ficam grávidas porque querem...” (linha 2). A autora, ao empregar “querem”, no presente do indicativo, confirma a sua certeza diante do fato expresso pelo verbo. ( ) “...os adolescentes a refletirem sobre as mudanças resultantes de uma gravidez na adolescência (linha 17). O uso do artigo “as” revela uma referência imprecisa ao substantivo “mudanças”. ( ) “Invariavelmente, descobrimos que o motivo que levou à gravidez está ligado à falta de perspectiva...” (linha 09). O sujeito sintático do verbo destacado é classificado como indeterminado. ( ) “apenas uma pequena fração engravida por acidente.” (linha 3). O verbo destacado é classificado como intransitivo. A sequência CORRETA é","opcoes":["F, V, F, V","V, V, F, F","V, F, F, V","V, F, F, F","F, F, V, V"],"correta":2,"explicacao":"Gabarito: <strong>V, F, F, V</strong>.","banca":"CPCON","ano":2017,"temas_relacionados":["transitividade"]},{"id":6275,"enunciado":"Leia as sentenças abaixo. I. “O ex-promotor tinha cerrados os olhos.” (Érico Veríssimo) II. O ex-promotor tinha cerrado os olhos. Assinale a alternativa que analisa corretamente as propriedades gramaticais e semânticas das sentenças acima.","opcoes":["Na sentença I, \"cerrados\" exerce a função de adjunto adnominal do substantivo \"olhos\", indicando uma característica intrínseca ao objeto; na sentença II, \"cerrado\" é o núcleo de um predicado verbal onde o verbo \"ter\" mantém sua transitividade plena e sentido original de posse.","Ambas as sentenças apresentam construções de voz passiva sintética, diferenciando-se apenas pela concordância atrativa. Na primeira, o adjetivo concorda com o núcleo do sujeito \"ex-promotor\" de forma indireta; na segunda, o verbo \"ter\" atua como auxiliar de um tempo composto do modo subjuntivo.","Na sentença I, o termo \"cerrados\" é um adjetivo com função de predicativo do objeto direto, conferindo à sentença um aspecto de estado resultante; na sentença II, ocorre uma locução verbal de tempo composto (Pretérito Maisque-perfeito do Indicativo), em que o particípio é invariável, priorizando o aspecto perfectivo da ação.","A primeira construção é um exemplo de \"particípio absoluto\", onde a concordância em gênero e número com o objeto direto é facultativa por razões estilísticas da literatura modernista; a segunda construção é a única gramaticalmente correta segundo a norma culta para indicar ações passadas anteriores a outras também passadas."],"correta":2,"explicacao":"Gabarito: <strong>Na sentença I, o termo \"cerrados\" é um adjetivo com função de predicativo do objeto direto, conferindo à sentença um aspecto de estado resultante; na sentença II, ocorre uma locução verbal de tempo composto (Pretérito Maisque-perfeito do Indicativo), em que o particípio é invariável, priorizando o aspecto perfectivo da ação.</strong>.","banca":"CIAAR","ano":2026,"temas_relacionados":["transitividade"]},{"id":6290,"enunciado":"\"A instituição tem registros anteriores da reprodução de papagaios-do-mangue e periquitos-rei na natureza, mesmo sendo oriundos de cativeiro.\" Com base na regência nominal e verbal do vocábulo 'oriundo' assinale a alternativa correta. I.O adjetivo 'oriundos' rege complemento introduzido pela preposição 'de', sendo inadequado seu emprego sem essa preposição, pois a regência nominal do termo exige tal elemento para indicar a relação de procedência expressa no trecho. II.O adjetivo 'oriundo' compartilha a mesma regência dos adjetivos 'contrário' e 'sensível', uma vez que os três regem complemento introduzido pela preposição 'de', estabelecendo relação de procedência, oposição e receptividade, respectivamente. III.O substantivo 'reprodução' rege complemento introduzido pela preposição 'de', seguindo a mesma regência do verbo 'reproduzir', do qual deriva, o que evidencia que a regência nominal frequentemente acompanha a regência do verbo primitivo correspondente. IV.O verbo 'ter', neste contexto, atua como transitivo direto e rege objeto direto sem preposição, podendo ser substituído pelo verbo 'possuir' mantendo o sentido e correção gramatical, uma vez que a regência de ambos não necessita de preposição. Assinale a alternativa que apresenta as proposições corretas.","opcoes":["I e IV, apenas.","I, II, III e IV.","I e II, apenas.","III e IV, apenas."],"correta":0,"explicacao":"Gabarito: <strong>I e IV, apenas.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["transitividade"]},{"id":6667,"enunciado":"No Texto II, a fala Eu não durmo carrega um forte impacto semântico para a ironia da charge. Do ponto de vista da análise sintática e morfológica, assinale a alternativa que apresenta uma afirmação CORRETA sobre a estrutura dessa oração.","opcoes":["O sujeito é classificado como oculto ou elíptico, uma vez que a desinência número-pessoal do verbo é suficiente para indicar a primeira pessoa do singular.","O termo não modifica o sentido do verbo e funciona sintaticamente como um adjunto adnominal.","O verbo durmo é intransitivo, pois possui sentido completo e não exige complemento nominal ou verbal paraÍazer sentido no contexto.","O enunciado constitui-se como um período composto por coordenação, formado por duas oraçôes unidas sem conectivo."],"correta":2,"explicacao":"Gabarito: <strong>O verbo durmo é intransitivo, pois possui sentido completo e não exige complemento nominal ou verbal paraÍazer sentido no contexto.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["transitividade"]},{"id":6712,"enunciado":"No trecho, “É preciso lembrar insistentemente a sabedoria emanada dos muitos modos como a vida se expressa no planeta no qual habitamos […]”, a expressão em destaque","opcoes":["pode ser substituída, sem prejuízo de sentido, por “em cujo”, na medida em que indica posse (“em nosso planeta”).","tem valor pronominal, uma vez que opera, na oração, substituição ao sujeito “planeta”, que lhe antecede.","pode ser substituída, sem prejuízo de sentido, tanto por “em que”, quanto por “que”, diante da bitransitividade do verbo “habitar”.","se trata de uma preposição, cuja função sintática é a de estabelecer a devida regência dos termos da oração."],"correta":2,"explicacao":"Gabarito: <strong>pode ser substituída, sem prejuízo de sentido, tanto por “em que”, quanto por “que”, diante da bitransitividade do verbo “habitar”.</strong>.","banca":"IV - UFG","ano":2026,"temas_relacionados":["transitividade"]},{"id":6727,"enunciado":"\"Minha professora do jardim da infância me ensinava muito sobre Leonardo da Vinci.\" Considerando a análise sintática dos termos presentes no trecho, marque com V as afirmativas verdadeiras ou com F as falsas. (__)O verbo 'ensinar' apresenta sujeito simples, explícito na oração, assim como na frase 'Faz-se chave aqui'. (__)O 'me' é pronome oblíquo átono que exerce função de objeto direto, pois o verbo 'ensinar' nessa construção é transitivo direto e indireto e a expressão 'muito sobre Leonardo da Vinci' exerce a função de objeto indireto. (__)O vocábulo 'muito' é advérbio de intensidade que modifica o verbo 'ensinar', exercendo função de adjunto adverbial. (__)O pronome 'me', no contexto, desempenha a mesma função sintática que exerce em 'Carla me telefonou ontem' Assinale a alternativa que apresenta a sequência correta dos itens acima, de cima para baixo.","opcoes":["F, V, F, F.","V, V, V, F.","V, V, F, V.","V, F, V, V."],"correta":3,"explicacao":"Gabarito: <strong>V, F, V, V.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["transitividade"]},{"id":6741,"enunciado":"Analise a estrutura morfológica dos termos destacados no título do texto 1: \"Superendividamento: A lei que protege quem não consegue pagar\". A alternativa que apresenta a classificação correta e completa de cada vocábulo destacado na sequência que estão no trecho acima é","opcoes":["substantivo comum – pronome relativo – pronome demonstrativo – verbo regular, 3ª pessoa do singular do pretérito perfeito.","substantivo concreto – conjunção integrante – pronome relativo – verbo intransitivo, 3ª pessoa do singular do presente do subjuntivo.","substantivo próprio – conjunção subordinativa – pronome indefinido – verbo irregular, 3ª pessoa do singular do presente do indicativo.","substantivo abstrato – pronome relativo – pronome relativo sem antecedente – verbo irregular, 3ª pessoa do singular do presente do indicativo.","substantivo abstrato – pronome relativo – pronome indefinido substantivo – verbo transitivo direto, 3ª pessoa do singular do presente do indicativo."],"correta":3,"explicacao":"Gabarito: <strong>substantivo abstrato – pronome relativo – pronome relativo sem antecedente – verbo irregular, 3ª pessoa do singular do presente do indicativo.</strong>.","banca":"CEFET-BA","ano":2026,"temas_relacionados":["transitividade"]},{"id":6743,"enunciado":"\"Minha professora do jardim da infância me ensinava muito sobre Leonardo da Vinci.\" Considerando a análise sintática dos termos presentes no trecho, marque com V as afirmativas verdadeiras ou com F as falsas. (__)O verbo 'ensinar' apresenta sujeito simples, explícito na oração, assim como na frase 'Faz-se chave aqui'. (__) O 'me' é pronome oblíquo átono que exerce função de objeto direto, pois o verbo 'ensinar' nessa construção é transitivo direto e indireto e a expressão 'muito sobre Leonardo da Vinci' exerce a função de objeto indireto. (__)O vocábulo 'muito' é advérbio de intensidade que modifica o verbo 'ensinar', exercendo função de adjunto adverbial. (__)O pronome 'me', no contexto, desempenha a mesma função sintática que exerce em 'Carla me telefonou ontem'. Assinale a alternativa que apresenta a sequência correta dos itens acima, de cima para baixo.","opcoes":["V, V, V, F.","V, F, V, V.","F, V, F, F.","V, V, F, V."],"correta":1,"explicacao":"Gabarito: <strong>V, F, V, V.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["transitividade"]},{"id":6755,"enunciado":"\"O avanço reduziu desigualdades regionais e levou internet de qualidade a escolas antes isoladas digitalmente.\" Considerando a regência dos verbos utilizados no trecho, analise as afirmativas a seguir: I.O verbo levar, no trecho, apresenta dupla transitividade, sendo o complemento sem preposição seu objeto direto e o complemento introduzido por preposição seu objeto indireto, ambos exigidos pela predicação verbal. II.O verbo 'reduzir' é transitivo direto, tendo como objeto direto 'desigualdades regionais', dispensando complemento preposicionado. III.O verbo 'levar' atua como transitivo direto, pois exige complemento sem preposição, e a expressão subsequente desempenha a função de adjunto adverbial de lugar, expressando o espaço físico em que se desenvolve a ação verbal. IV.Se a expressão 'escolas' estivesse no singular, haveria ocorrência obrigatória de crase, resultante da contração entre a preposição exigida pelo contexto e o artigo definido feminino 'a'. Assinale a alternativa que apresenta as proposições corretas.","opcoes":["II, apenas.","III e IV, apenas.","II e III, apenas.","I, II e IV, apenas."],"correta":3,"explicacao":"Gabarito: <strong>I, II e IV, apenas.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["transitividade","crase"]},{"id":6782,"enunciado":"Economistas reconhecem que a abertura econômica traz benefícios no longo prazo, mas alertam que a velocidade das mudanças prejudica empresas que precisariam de mais tempo para adaptação. Sobre a regência dos verbos empregados no trecho, assinale a alternativa correta.","opcoes":["O verbo “traz” apresenta dupla transitividade, já que o termo “benefícios” funciona como objeto indireto da forma verbal.","O verbo “reconhecem” está empregado como verbo transitivo indireto, exigindo complemento introduzido pela preposição “que”.","O verbo “alertam” exige objeto indireto introduzido por preposição, razão pela qual a oração introduzida por “que” exerce função adverbial no período.","O verbo “alertam” admite, no contexto apresentado, construção transitiva indireta, já que a oração introduzida por “que” recupera semanticamente o conteúdo sobre o qual recai o alerta expresso no período.","O verbo \"prejudica\" está empregado como verbo transitivo direto, estabelecendo relação sem preposição com o termo \"empresas\"."],"correta":4,"explicacao":"Gabarito: <strong>O verbo \"prejudica\" está empregado como verbo transitivo direto, estabelecendo relação sem preposição com o termo \"empresas\".</strong>.","banca":"AMAUC","ano":2026,"temas_relacionados":["transitividade"]},{"id":6793,"enunciado":"\"O documento serve de instrumento para que estados, municípios e sociedade civil conheçam e implantem os novos normativos de gestão cultural aprovados desde 2023\". Com base na regência verbal do trecho extraído da Agencia Brasil, analise as afirmativas a seguir: I. O verbo 'servir' atua como intransitivo apresentando apenas adjuntos adverbiais de instrumento e finalidade. II. O verbo 'implantar' atua como transitivo direto, sendo que essa mesma transitividade é compartilhada pelo verbo 'conhecer', igualmente transitivo direto no trecho, o que confirma que ambos os verbos pertencem à mesma categoria de transitividade e regem seus complementos sem preposição. III. A transitividade do verbo 'conhecer' no trecho é a mesma observada na frase 'À presença do juiz, o réu conheceu seus crimes'. IV. O verbo 'servir' pode atuar como intransitivo, como na frase 'Fora contratada para servir e o fazia muito bem'. Assinale a alternativa que apresenta as proposições corretas.","opcoes":["I, II, III e IV.","I, III e IV, apenas.","II, III e IV, apenas.","II, apenas."],"correta":2,"explicacao":"Gabarito: <strong>II, III e IV, apenas.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["transitividade"]},{"id":6798,"enunciado":"\"O documento serve de instrumento para que estados, municípios e sociedade civil conheçam e implantem os novos normativos de gestão cultural aprovados desde 2023\". Com base na regência verbal do trecho extraído da Agencia Brasil, analise as afirmativas a seguir: I.O verbo 'servir' atua como intransitivo apresentando apenas adjuntos adverbiais de instrumento e finalidade. II.O verbo 'implantar' atua como transitivo direto, sendo que essa mesma transitividade é compartilhada pelo verbo 'conhecer', igualmente transitivo direto no trecho, o que confirma que ambos os verbos pertencem à mesma categoria de transitividade e regem seus complementos sem preposição. III. A transitividade do verbo 'conhecer' no trecho é a mesma observada na frase 'À presença do juiz, o réu conheceu seus crimes'. IV. O verbo 'servir' pode atuar como intransitivo, como na frase 'Fora contratada para servir e o fazia muito bem'. Assinale a alternativa que apresenta as proposições corretas.","opcoes":["I, II, III e IV.","I, III e IV, apenas.","II, apenas.","II, III e IV, apenas."],"correta":3,"explicacao":"Gabarito: <strong>II, III e IV, apenas.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["transitividade"]},{"id":6801,"enunciado":"\"O documento serve de instrumento para que estados, municípios e sociedade civil conheçam e implantem os novos normativos de gestão cultural aprovados desde 2023\". Com base na regência verbal do trecho extraído da Agencia Brasil, analise as afirmativas a seguir: I. O verbo \"servir\" atua como intransitivo, apresentando apenas adjuntos adverbiais de instrumento e finalidade. II. O verbo \"implantar\" atua como transitivo direto, sendo que essa mesma transitividade é compartilhada pelo verbo \"conhecer\", igualmente transitivo direto no trecho, o que confirma que ambos os verbos pertencem à mesma categoria de transitividade e regem seus complementos sem preposição. III. A transitividade do verbo \"conhecer\" no trecho é a mesma observada na frase: \"À presença do juiz, o réu conheceu seus crimes\". IV. O verbo \"servir\" pode atuar como intransitivo, como na frase: \"Fora contratada para servir e o fazia muito bem\". Assinale a alternativa que apresenta as proposições corretas.","opcoes":["II, apenas.","III e IV, apenas.","I, III e IV, apenas.","I, II, III e IV"],"correta":1,"explicacao":"Gabarito: <strong>III e IV, apenas.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["transitividade"]},{"id":6809,"enunciado":"\"Segundo uma pesquisa nacional conduzida pela Fundação Carlos Chagas (FCC) em parceria com o Ministério da Educação (MEC), 71,7% dos gestores escolares afirmam ter dificuldades para dialogar sobre o enfrentamento às violências.\" Considerando a regência verbal, marque com V as afirmativas verdadeiras ou com F as falsas. (__)O verbo 'dialogar' classifica-se como transitivo indireto, uma vez que seu complemento é obrigatoriamente introduzido por preposição. No trecho em análise, o verbo apresenta dois complementos indiretos explícitos, 'sobre o enfrentamento' e 'às violências', sendo o segundo introduzido pela preposição 'a' contraída com o artigo definido feminino plural 'as', o que justifica o emprego da crase em 'às violências'. (__)O verbo 'dialogar' atua como transitivo indireto, uma vez que seu complemento é obrigatoriamente introduzido por preposição, sem a qual o sentido do verbo permanece incompleto. Em outros contextos, o mesmo verbo admite a preposição 'com' para introduzir o complemento que indica o interlocutor, configurando, em ambos os casos, construções igualmente corretas do ponto de vista da norma culta, com distinção semântica determinada pela escolha da preposição. (__)O verbo 'afirmar' classifica-se como transitivo direto, exigindo complemento sem preposição. No período em análise, o objeto direto é representado por uma oração reduzida de infinitivo, 'ter dificuldades para dialogar sobre o enfrentamento às violências', denominada oração subordinada substantiva objetiva direta reduzida de infinitivo, que poderia ser substituída, sem prejuízo gramatical, pela forma desenvolvida 'que têm dificuldades para dialogar sobre o enfrentamento às violências'. Assinale a alternativa que apresenta a sequência correta dos itens acima, de cima para baixo.","opcoes":["V, F, V.","F, V, V.","V, F, F.","F, V, F."],"correta":1,"explicacao":"Gabarito: <strong>F, V, V.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["transitividade","crase"]},{"id":6815,"enunciado":"\"Segundo uma pesquisa nacional conduzida pela Fundação Carlos Chagas (FCC) em parceria com o Ministério da Educação (MEC), 71,7% dos gestores escolares afirmam ter dificuldades para dialogar sobre o enfrentamento às violências.\" Considerando a regência verbal, marque com V as afirmativas verdadeiras ou com F as falsas. (__) O verbo 'dialogar' classifica-se como transitivo indireto, uma vez que seu complemento é obrigatoriamente introduzido por preposição. No trecho em análise, o verbo apresenta dois complementos indiretos explícitos, 'sobre o enfrentamento' e 'às violências', sendo o segundo introduzido pela preposição 'a' contraída com o artigo definido feminino plural 'as', o que justifica o emprego da crase em 'às violências'. (__) O verbo 'dialogar' atua como transitivo indireto, uma vez que seu complemento é obrigatoriamente introduzido por preposição, sem a qual o sentido do verbo permanece incompleto. Em outros contextos, o mesmo verbo admite a preposição 'com' para introduzir o complemento que indica o interlocutor, configurando, em ambos os casos, construções igualmente corretas do ponto de vista da norma culta, com distinção semântica determinada pela escolha da preposição. (__) O verbo 'afirmar' classifica-se como transitivo direto, exigindo complemento sem preposição. No período em análise, o objeto direto é representado por uma oração reduzida de infinitivo, 'ter dificuldades para dialogar sobre o enfrentamento às violências', denominada oração subordinada substantiva objetiva direta reduzida de infinitivo, que poderia ser substituída, sem prejuízo gramatical, pela forma desenvolvida 'que têm dificuldades para dialogar sobre o enfrentamento às violências'. Assinale a alternativa que apresenta a sequência correta dos itens acima, de cima para baixo.","opcoes":["V, F, F.","V, F, V.","F, V, F.","F, V, V."],"correta":3,"explicacao":"Gabarito: <strong>F, V, V.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["transitividade","crase"]},{"id":6817,"enunciado":"\"Para uma das diretoras da associação dos moradores, Vânia Lúcia Duarte, de 50 anos, o reconhecimento ajuda na preservação de uma comunidade já espremida pela especulação imobiliária.\" Com base na regência verbal e nominal, analise as afirmativas a seguir: I. O verbo 'ajudar' atua no trecho como transitivo indireto, no entanto, pode ser encontrado como transitivo direto, como em 'Eu preciso de alguém que me ajude'. II. O verbo 'ajudar', no sentido de auxiliar alguém na realização de uma ação, classifica-se como transitivo direto quando seguido de infinitivo, como em \"Ele o ajudou a conseguir emprego\", sendo a preposição 'a' elemento de ligação sem função sintática. III. A expressão 'pela especulação imobiliária' funciona como complemento nominal do adjetivo 'espremida', exigido pela regência desse termo. IV. O verbo 'ajudar' pode ser usado como pronominal, como em 'Se ele não se ajudasse, não teria sarado', construção gramaticalmente correta, de acordo com a norma-padrão. Assinale a alternativa que apresenta as proposições corretas.","opcoes":["II e III, apenas.","I, apenas.","II, apenas.","I e IV, apenas."],"correta":3,"explicacao":"Gabarito: <strong>I e IV, apenas.</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["transitividade"]},{"id":6822,"enunciado":"\"A programação reuniu diversas atividades com o tema central 'Patrimônio e Reparação', convidando funcionários do Instituto e a sociedade a se engajarem em ações que destacassem o papel das políticas de Patrimônio Cultural na promoção da Igualdade Racial e na afirmação da centralidade da herança e do legado afro-brasileiro.\" Considerando a regência verbal, marque com V as afirmativas verdadeiras ou com F as falsas. (__) O verbo 'convidar', no trecho, é transitivo direto, tendo 'funcionários do Instituto e a sociedade' como o objeto direto. A preposição 'a' que antecede 'se engajarem' introduz um complemento verbal em forma de infinitivo, indicando a ação para a qual os funcionários e a sociedade foram convidados. (__) O verbo 'convidar' é transitivo direto e indireto simultaneamente, tendo 'funcionários do Instituto e a sociedade' como objeto direto e 'a se engajarem em ações que destacassem o papel das políticas de Patrimônio Cultural na promoção da Igualdade Racial' como objeto indireto, introduzido pela preposição 'a', que integra obrigatoriamente a regência do verbo. (__) O verbo 'engajar-se' é transitivo direto pronominal, tendo 'em ações que destacassem o papel das políticas de Patrimônio Cultural na promoção da Igualdade Racial' como objeto direto preposicionado. (__) O verbo 'destacar' atua como bitransitivo, exigindo complemento direto e outro indireto introduzido pela preposição 'de', que indica o conjunto do qual o referente se destaca. Assinale a sequência que preenche corretamente os itens acima, na ordem.","opcoes":["V, F, V, V","V, F, V, F","F, V, F, F","F, V, F, V,"],"correta":2,"explicacao":"Gabarito: <strong>F, V, F, F</strong>.","banca":"AMEOSC","ano":2026,"temas_relacionados":["transitividade"]},{"id":6832,"enunciado":"Em “não houve nenhuma oportunidade de diálogo de demonstrar o que é viável”, é CORRETO afirmar, de acordo com os termos da oração, que:","opcoes":["O termo ‘nenhuma oportunidade de diálogo’ exerce a função de sujeito do verbo ‘haver’.","O verbo ‘haver’ é impessoal e transitivo direto.","O termo ‘viável’ exerce a função de complemento nominal.","O verbo ‘haver’ é pessoal e concorda com o sujeito da oração."],"correta":1,"explicacao":"Gabarito: <strong>O verbo ‘haver’ é impessoal e transitivo direto.</strong>.","banca":"INBRASP","ano":2026,"temas_relacionados":["transitividade"]},{"id":6856,"enunciado":"\"...um comportamento que, segundo eles, pode ajudar os animais a evitar problemas estomacais causados pelo consumo de lanches humanos.\" Com base na regência do verbo 'ajudar', analise as afirmativas e assinale a correta.","opcoes":["O verbo 'ajudar' atua como transitivo direto, podendo ser encontrado como pronominal, como em 'Ajudava-se dos pés e das mãos para subir na árvore'.","O verbo 'ajudar' atua como transitivo direto, assim como se observa em 'Gosta de ajudar quem está em dificuldades'.","O verbo 'ajudar' é intransitivo, não exigindo complemento verbal no contexto apresentado.","O verbo 'ajudar' atua como transitivo direto e indireto, exigindo simultaneamente objeto direto e complemento preposicionado."],"correta":3,"explicacao":"Gabarito: <strong>O verbo 'ajudar' atua como transitivo direto e indireto, exigindo simultaneamente objeto direto e complemento preposicionado.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["transitividade"]},{"id":6860,"enunciado":"Ao reescrever o período “Existe amor em SP, mas é uma coisa que nós precisamos buscar e construir, dia após dia”, de modo que o termo “amor” seja substituído pelo substantivo plural “amores genuínos”, assinale a alternativa que apresenta a concordância verbal e nominal adequada conforme a norma-padrão.","opcoes":["“Existe amores genuínos em SP, mas é uma coisa que nós precisamos buscar e construir, dia após dia” — concordância aceita pela norma culta porque o verbo “existir”, quando intransitivo e anteposto ao sujeito, pode permanecer no singular independentemente do número do substantivo que o segue.","“Existem amores genuínos em SP, mas é uma coisa que nós precisamos buscar e construir, dia após dia” — concordância em que somente o primeiro verbo é pluralizado por exigência do sujeito composto, enquanto o segundo verbo (“é”) permanece no singular por referência genérica ao conceito.","“Existem amores genuínos em SP, mas são coisas que nós precisamos buscar e construir, dia após dia” — concordância em que o verbo “existir”, transitado para o plural, concorda com o sujeito pluralizado; e o predicativo “coisas” também vai ao plural por concordância com o sujeito retomado pelo verbo “ser”.","“Existe amores genuínos em SP, mas são coisas que nós precisamos buscar e construir, dia após dia” — concordância em que o verbo existencial permanece no singular por tratar-se de construção existencial impessoal, enquanto o predicativo é pluralizado por concordância com o sujeito da oração seguinte."],"correta":2,"explicacao":"Gabarito: <strong>“Existem amores genuínos em SP, mas são coisas que nós precisamos buscar e construir, dia após dia” — concordância em que o verbo “existir”, transitado para o plural, concorda com o sujeito pluralizado; e o predicativo “coisas” também vai ao plural por concordância com o sujeito retomado pelo verbo “ser”.</strong>.","banca":"IDIB","ano":2026,"temas_relacionados":["transitividade"]},{"id":6896,"enunciado":"Observe os verbos destacados e, em seguida, assinale a opção que apresenta, respectivamente, a classificação correta, aplicada ao contexto da sentença. Aquele homem era um visionário que vivia uma vida simples, pois acreditava que devia sua gratidão aos amigos antes de finalmente morrer em paz.","opcoes":["Transitivo direto; transitivo direto; intransitivo e transitivo direto e indireto.","Verbo de ligação; transitivo direto; transitivo direto e indireto e intransitivo.","Intransitivo; transitivo direto e indireto; transitivo direto e verbo de ligação.","Verbo de ligação; intransitivo; transitivo direto e indireto e transitivo direto."],"correta":1,"explicacao":"Gabarito: <strong>Verbo de ligação; transitivo direto; transitivo direto e indireto e intransitivo.</strong>.","banca":"CIAAR","ano":2026,"temas_relacionados":["transitividade"]},{"id":6897,"enunciado":"Leia as sentenças abaixo. I. “O ex-promotor tinha cerrados os olhos.” (Érico Veríssimo) II. O ex-promotor tinha cerrado os olhos. Assinale a alternativa que analisa corretamente as propriedades gramaticais e semânticas das sentenças acima.","opcoes":["Na sentença I, \"cerrados\" exerce a função de adjunto adnominal do substantivo \"olhos\", indicando uma característica intrínseca ao objeto; na sentença II, \"cerrado\" é o núcleo de um predicado verbal onde o verbo \"ter\" mantém sua transitividade plena e sentido original de posse.","Ambas as sentenças apresentam construções de voz passiva sintética, diferenciando-se apenas pela concordância atrativa. Na primeira, o adjetivo concorda com o núcleo do sujeito \"ex-promotor\" de forma indireta; na segunda, o verbo \"ter\" atua como auxiliar de um tempo composto do modo subjuntivo.","Na sentença I, o termo \"cerrados\" é um adjetivo com função de predicativo do objeto direto, conferindo à sentença um aspecto de estado resultante; na sentença II, ocorre uma locução verbal de tempo composto (Pretérito Mais que-perfeito do Indicativo), em que o particípio é invariável, priorizando o aspecto perfectivo da ação.","A primeira construção é um exemplo de \"particípio absoluto\", onde a concordância em gênero e número com o objeto direto é facultativa por razões estilísticas da literatura modernista; a segunda construção é a única gramaticalmente correta segundo a norma culta para indicar ações passadas anteriores a outras também passadas."],"correta":2,"explicacao":"Gabarito: <strong>Na sentença I, o termo \"cerrados\" é um adjetivo com função de predicativo do objeto direto, conferindo à sentença um aspecto de estado resultante; na sentença II, ocorre uma locução verbal de tempo composto (Pretérito Mais que-perfeito do Indicativo), em que o particípio é invariável, priorizando o aspecto perfectivo da ação.</strong>.","banca":"CIAAR","ano":2026,"temas_relacionados":["transitividade"]},{"id":6934,"enunciado":"\"Em uma terceira comunidade, onde não havia cacatuas treinadas, os papagaios demoraram quatro dias a experimentar os novos alimentos.\" Analise as afirmativas a seguir considerando a função sintática e assinale a afirmativa incorreta.","opcoes":["O verbo 'haver' é impessoal e transitivo, empregado no sentido de 'existir', razão pela qual não apresenta sujeito na oração e permanece obrigatoriamente na terceira pessoa do singular, tendo 'cacatuas treinadas' como seu objeto direto.","A oração 'onde não havia cacatuas treinadas' é uma oração subordinada adjetiva, pois o pronome relativo 'onde' retoma 'terceira comunidade', acrescentando uma informação adicional sobre a comunidade referida.","A expressão 'em uma terceira comunidade' exerce função de adjunto adverbial de lugar, indicando o espaço onde ocorreu o fato narrado, separado por vírgula obrigatoriamente.","A expressão 'a experimentar os novos alimentos' exerce função de adjunto adverbial de finalidade, indicando o propósito pelo qual os papagaios demoraram quatro dias para alimentar-se, tendo a preposição 'a' valor de finalidade."],"correta":3,"explicacao":"Gabarito: <strong>A expressão 'a experimentar os novos alimentos' exerce função de adjunto adverbial de finalidade, indicando o propósito pelo qual os papagaios demoraram quatro dias para alimentar-se, tendo a preposição 'a' valor de finalidade.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["transitividade"]},{"id":7040,"enunciado":"A análise sintática, morfológica e ortográfica de uma oração permite compreender as relações de dependência entre os termos e as regras que regem a escrita na norma-padrão. Diante disso, analise a oração O resultado atual representa um acréscimo de 94.137 postos de trabalho e, com base nela, assinale a alternativa INCORRETA.","opcoes":["O verbo representa é um verbo de ligação, cuja função e conectar o sujeito a uma característica do predicativo.","A palavra acréscimo é acentuada por ser uma proparoxítona, já que a antepenúltima sílaba é a tônica.","O termo O resultado atual exerce a função de sujeito simples, cujo núcleo é o substantivo resultado.","O vocábulo de, em sua segunda ocorrência na frase, e classificado gramaticalmente como preposição.","O termo atual funciona como adjunto adnominal, pois qualifica o vocábulo resultado."],"correta":0,"explicacao":"Gabarito: <strong>O verbo representa é um verbo de ligação, cuja função e conectar o sujeito a uma característica do predicativo.</strong>.","banca":"Instituto Legalle","ano":2026,"temas_relacionados":["transitividade","silabas","proparoxitonas"]},{"id":7106,"enunciado":"Sobre o trecho “A escola investe em ambientes digitais de aprendizagem...” (10§), a análise da função morfossintática, só está correta na opção:","opcoes":["Em ambientes digitais de aprendizagem = objeto indireto.","A escola = sujeito elíptico","Investe = verbo intransitivo","Em = conjunção subordinativa","De = pronome relativo."],"correta":0,"explicacao":"Gabarito: <strong>Em ambientes digitais de aprendizagem = objeto indireto.</strong>.","banca":"IVIN","ano":2025,"temas_relacionados":["transitividade"]},{"id":7112,"enunciado":"Considere que o verbo simpatizar é transitivo indireto no contexto “Os amigos esperavam que ela simpatizasse …. a nova participante do grupo, afinal, elas teriam que conviver pelos próximos dias”. A preposição adequada para ligá-lo ao seu complemento é:","opcoes":["para.","com.","perante.","a.","de."],"correta":1,"explicacao":"Gabarito: <strong>com.</strong>.","banca":"Avança SP","ano":2025,"temas_relacionados":["transitividade"]},{"id":7119,"enunciado":"Leia as sentenças a seguir. I. O Itumbiara liderou o Campeonato de ponta a ponta. II. Nas casas de campo, apanhava de chicote. A preposição “de”, além de tradicionalmente cumprir sua função gramatical no sistema de transitividade, desempenha uma função lexical em ambas as ocorrências. Respectivamente, nas duas sentenças acima, a preposição “de” indica relações semânticas de","opcoes":["extensão e posição.","extensão e instrumento.","posse e posição.","posse e instrumento."],"correta":1,"explicacao":"Gabarito: <strong>extensão e instrumento.</strong>.","banca":"IV - UFG","ano":2025,"temas_relacionados":["transitividade"]},{"id":7131,"enunciado":"No trecho \"Recordo também de um trabalho acadêmico, onde meu orientador insistiu na formulação correta da questão-chave antes de avançar\", o verbo \"recordar\" foi utilizado corretamente de acordo com sua regência. Assinale a alternativa que indica a classificação correta de sua transitividade e a preposição exigida pelo verbo.","opcoes":["Verbo transitivo indireto, exigindo a preposição \"de\".","Verbo transitivo direto, não exigindo preposição.","Verbo intransitivo, não necessitando de complementos para completar seu sentido.","Verbo bitransitivo, podendo exigir complementos com ou sem preposição."],"correta":0,"explicacao":"Gabarito: <strong>Verbo transitivo indireto, exigindo a preposição \"de\".</strong>.","banca":"IBAM","ano":2025,"temas_relacionados":["transitividade"]},{"id":7363,"enunciado":"A respeito da estrutura morfossintática, das relações fonéticas e dos mecanismos de coesão textual presentes na tirinha, assinale a alternativa CORRETA.","opcoes":["Na frase do último quadrinho, o verbo ouvir e transitivo indireto e o segmento o canto das cigarras funciona sintaticamente como seu objeto indireto.","O segmento inicial ou- do verbo ouvir constitui um dígrafo vocállco, razão pela qual a palavra apresenta menos fonemas do que letras em sua contagem.","O sujeito da oração principal do primeiro quadrinho e classificado como simples, tendo por núcleo o pronome pessoal do caso reto Elas.","O referente do pronome Elas é explicitado logo no primeiro quadrinho da tirinha por meio de elementos evidentes na imagem."],"correta":2,"explicacao":"Gabarito: <strong>O sujeito da oração principal do primeiro quadrinho e classificado como simples, tendo por núcleo o pronome pessoal do caso reto Elas.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["transitividade"]},{"id":7404,"enunciado":"No trecho “o que o levou a acreditar que esta seja a chave para o futuro do armazenamento de dados”, retirado do texto, considerando a análise da estrutura sintática, é correto afirmar que:","opcoes":["O pronome “o” está em próclise devido à atração do pronome relativo.","A palavra “esta” exerce a função sintática de objeto direto de “levou”.","O verbo “seja” estabelece concordância com o substantivo “dados”.","O verbo “levar” é transitivo direto e dispensa preposição em seu complemento."],"correta":0,"explicacao":"Gabarito: <strong>O pronome “o” está em próclise devido à atração do pronome relativo.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["transitividade"]},{"id":7412,"enunciado":"\"Foram a inquietude e a curiosidade de Thiago Alves dos Santos, seu aluno do terceiro ano do ensino médio, que levaram ao resultado final. Como eles já haviam desenvolvido um papel à base de folhas de pequi, o estudante perguntou se seria possível produzir também tecido a partir do material.\" Com base na análise sintática, julgue as afirmativas a seguir: I. A forma verbal 'foram' encontra-se no plural em razão de concordar com um termo essencial da oração, representado por dois núcleos, diferentemente da construção 'É bom resolver o problema', em que o sujeito não está determinado na frase. II. O verbo 'haver' apresenta comportamento intransitivo, uma vez que integra uma locução verbal e, de forma isolada, não estabelece relação de transitividade, atuando apenas como verbo auxiliar do verbo 'desenvolver'. III. O pronome relativo 'que' em 'que levaram...' exerce a mesma função sintática do pronome 'a', considerando o verbo 'falar', na construção 'Mandei-a falar com o responsável pela venda'. IV. A expressão 'tecido' exerce a mesma função sintática do pronome 'que' na frase 'O livro que eu li é genial!'. Após análise, assinale a alternativa que apresenta apenas as proposições CORRETAS.","opcoes":["II e IV, apenas.","I, III e IV, apenas.","I, II e IV, apenas.","I e II, apenas.","I e III, apenas."],"correta":1,"explicacao":"Gabarito: <strong>I, III e IV, apenas.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["transitividade"]},{"id":7445,"enunciado":"\"Foram a inquietude e a curiosidade de Thiago Alves dos Santos, seu aluno do terceiro ano do ensino médio, que levaram ao resultado final. Como eles já haviam desenvolvido um papel à base de folhas de pequi, o estudante perguntou se seria possível produzir também tecido a partir do material.\" Com base na análise sintática, julgue as afirmativas a seguir: I. A forma verbal 'foram' encontra-se no plural em razão de concordar com um termo essencial da oração, representado por dois núcleos, diferentemente da construção 'É bom resolver o problema', em que o sujeito não está determinado na frase. II. O verbo 'haver' apresenta comportamento intransitivo, uma vez que integra uma locução verbal e, de forma isolada, não estabelece relação de transitividade, atuando apenas como verbo auxiliar do verbo 'desenvolver'. III. O pronome relativo 'que' em 'que levaram...' exerce a mesma função sintática do pronome 'a', considerando o verbo 'falar', na construção 'Mandei-a falar com o responsável pela venda'. IV. A expressão 'tecido' exerce a mesma função sintática do pronome 'que' na frase 'O livro que eu li é genial!'. Após análise, assinale a alternativa que apresenta apenas as proposições CORRETAS.","opcoes":["I, II e IV, apenas.","I e II, apenas.","I, III e IV, apenas.","I e III, apenas.","II e IV, apenas"],"correta":2,"explicacao":"Gabarito: <strong>I, III e IV, apenas.</strong>.","banca":"IGEDUC","ano":2026,"temas_relacionados":["transitividade"]},{"id":7454,"enunciado":"Ao avaliar a sintaxe do pronome relativo no retângulo em destaque no sétimo parágrafo e suas implicações de sentido, conclui-se que:","opcoes":["O pronome as quais atua como locução conjuntiva integrante, possuindo a função de completar a transitividade do substantivo abstrato monopólio.","O emprego de as quais introduz uma oração subordinada adjetiva restritiva voltada ao termo decisões, eximindo atividades da responsabilidade de gerar embates sociais.","O pronome as quais retoma o antecedente nominal composto certas atividades e decisões, exercendo a função sintática de sujeito do verbo acarretam.","Se as quais fosse substituído pelo pronome relativo universal que, incorreria em erro sintático, já que a norma veda a este pronome a retomada de antecedentes substantivos no plural."],"correta":2,"explicacao":"Gabarito: <strong>O pronome as quais retoma o antecedente nominal composto certas atividades e decisões, exercendo a função sintática de sujeito do verbo acarretam.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["transitividade"]},{"id":7485,"enunciado":"Leia as sentenças abaixo. I. “O ex-promotor tinha cerrados os olhos.” (Érico Veríssimo) II. O ex-promotor tinha cerrado os olhos. Assinale a alternativa que analisa corretamente as propriedades gramaticais e semânticas das sentenças acima.","opcoes":["Na sentença I, \"cerrados\" exerce a função de adjunto adnominal do substantivo \"olhos\", indicando uma característica intrínseca ao objeto; na sentença II, \"cerrado\" é o núcleo de um predicado verbal onde o verbo \"ter\" mantém sua transitividade plena e sentido original de posse.","Ambas as sentenças apresentam construções de voz passiva sintética, diferenciando-se apenas pela concordância atrativa. Na primeira, o adjetivo concorda com o núcleo do sujeito \"ex-promotor\" de forma indireta; na segunda, o verbo \"ter\" atua como auxiliar de um tempo composto do modo subjuntivo.","Na sentença I, o termo \"cerrados\" é um adjetivo com função de predicativo do objeto direto, conferindo à sentença um aspecto de estado resultante; na sentença II, ocorre uma locução verbal de tempo composto (Pretérito Mais-que-perfeito do Indicativo), em que o particípio é invariável, priorizando o aspecto perfectivo da ação.","A primeira construção é um exemplo de \"particípio absoluto\", onde a concordância em gênero e número com o objeto direto é facultativa por razões estilísticas da literatura modernista; a segunda construção é a única gramaticalmente correta segundo a norma culta para indicar ações passadas anteriores a outras também passadas."],"correta":2,"explicacao":"Gabarito: <strong>Na sentença I, o termo \"cerrados\" é um adjetivo com função de predicativo do objeto direto, conferindo à sentença um aspecto de estado resultante; na sentença II, ocorre uma locução verbal de tempo composto (Pretérito Mais-que-perfeito do Indicativo), em que o particípio é invariável, priorizando o aspecto perfectivo da ação.</strong>.","banca":"CIAAR","temas_relacionados":["transitividade"]},{"id":7487,"enunciado":"Considerando aspectos foneticos, sintáticos e morfologicos que estruturam a frase do texto, analise as partes que seguem: (1ª parte). A palavra música é acentuada graficamente por ser uma pa/avra paroxítona terminada em voga/. (2ª parte). O termo uma música exerce a função de objeto díreto da forma verbal cante, pois completa o sentrdo do verbo transitivo direto sem o auxího de preposíção. (3ª parte). O verbo dizer pertence à segunda conjugação, o que é evidenciado pela vogal temática -e- presente em sua forma de infinitívo. Pode-se afirmar que:","opcoes":["Apenas a 3ª parte está correta.","Apenas a 1ª e a 3ª partes estão corretas.","Apenas a 2ª e a 3ª partes estão corretas.","Todas as partes estão corretas."],"correta":2,"explicacao":"Gabarito: <strong>Apenas a 2ª e a 3ª partes estão corretas.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["transitividade","paroxitonas"]},{"id":7493,"enunciado":"Considerando as regras de regência verbal, é correto afirmar que o verbo destacado, na frase a seguir, comporta-se como um verbo: “A polícia da cidade de Providence deteve neste domingo, 14, um suspeito ligado ao ataque a tiros na Universidade Brown”. Disponível em: https://veja.abril.com.br/mundo/policia-detem-suspeito-ligado-a-ataque-a-tiros-na-universidade-brown-nos-eua/","opcoes":["intransitivo, pois não necessita de complemento verbal para dar sentido à ação do sujeito da frase.","transitivo indireto, pois exige um complemento preposicionado, introduzido pela preposição “ao” implícita.","transitivo direto, pois exige um complemento sem preposição, que funciona como objeto direto.","bitransitivo, pois apresenta dois complementos distintos, um direto e outro indireto, ambos necessários para a compreensão da ação verbal."],"correta":2,"explicacao":"Gabarito: <strong>transitivo direto, pois exige um complemento sem preposição, que funciona como objeto direto.</strong>.","banca":"Itame","ano":2026,"temas_relacionados":["transitividade"]},{"id":7500,"enunciado":"Analise o fragmento a seguir. “Quem espera que a vida Seja feita de ilusão Pode até ficar maluco Ou morrer na solidão.” A expressão “ficar maluco” apresenta um verbo que, nesse contexto, classifica-se como:","opcoes":["verbo transitivo direto, uma vez que exige complemento sem preposição para completar o sentido expresso no período.","verbo intransitivo, porque apresenta sentido completo, mas que não dispensa um termo que complemente sua significação.","verbo transitivo indireto, já que necessita de complemento introduzido por preposição obrigatória para possuir sentido completo.","verbo nocional de ação, pois indica uma atividade concreta praticada intencionalmente pelo sujeito da oração.","verbo de ligação, pois estabelece uma relação entre o sujeito e uma característica atribuída a ele, indicando mudança de estado."],"correta":4,"explicacao":"Gabarito: <strong>verbo de ligação, pois estabelece uma relação entre o sujeito e uma característica atribuída a ele, indicando mudança de estado.</strong>.","banca":"Ápice Consultoria","ano":2026,"temas_relacionados":["transitividade"]},{"id":7502,"enunciado":"Considerando a regência dos verbos presentes no texto-base, analise as afirmativas a seguir e identifique a incorreta.","opcoes":["Em 'muda o cérebro', o verbo 'mudar' é empregado como transitivo direto, regendo objeto direto sem preposição, admitindo, entretanto, o uso transitivo indireto com preposição em outros contextos, como em 'A família mudou de apartamento'.","Em 'Não há nada menos natural do que ler', o verbo 'haver' é impessoal e rege objeto direto, com complemento sem preposição, o que indica que o verbo, nesse contexto, é transitivo direto.","Em 'faltam na leitura digital', o verbo 'faltar' rege complemento introduzido por preposição, classificando-se como transitivo indireto, de modo que a substituição do complemento por pronome oblíquo exigiria a forma 'lhe'.","Em 'implica a aquisição de um código simbólico', o verbo 'implicar', no sentido de 'acarretar', rege objeto direto sem preposição, sendo, portanto, incorreto o uso da preposição 'em' após esse verbo nesse mesmo sentido."],"correta":2,"explicacao":"Gabarito: <strong>Em 'faltam na leitura digital', o verbo 'faltar' rege complemento introduzido por preposição, classificando-se como transitivo indireto, de modo que a substituição do complemento por pronome oblíquo exigiria a forma 'lhe'.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["transitividade"]},{"id":7531,"enunciado":"\"Microfones especiais podem nos ajudar a detectar ruídos inaudíveis para o ouvido humano, como os sons ultrassônicos emitidos pelos morcegos.\" Com base na regência verbal, assinale a alternativa correta.","opcoes":["O verbo 'poder' integra uma locução verbal e atua apenas como verbo auxiliar, sem exigir complemento próprio, enquanto o verbo 'detectar' funciona como verbo transitivo direto.","O verbo 'ajudar' atua como transitivo indireto, exigindo dois complementos indiretos; o pronome oblíquo átono 'nos' e a forma verbal 'detectar', que introduz o outro complemento.","O verbo 'ajudar' atua como transitivo direto e indireto, tendo o pronome oblíquo 'nos' como objeto direto, enquanto o verbo 'detectar' atua como transitivo direto.","O verbo 'poder' atua como verbo transitivo direto e indireto, tendo o pronome 'nos' como objeto direto e a oração introduzida pela preposição 'a' como objeto indireto."],"correta":2,"explicacao":"Gabarito: <strong>O verbo 'ajudar' atua como transitivo direto e indireto, tendo o pronome oblíquo 'nos' como objeto direto, enquanto o verbo 'detectar' atua como transitivo direto.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["transitividade"]},{"id":7567,"enunciado":"Sobre os vocábulos e expressões destacados a seguir, extraídos do texto 1, analise as assertivas e identifique com V as verdadeiras e com F as falsas. ( ) No trecho: “O aposentado recebe ligações [...]” (linha 22), o termo destacado é um pronome demonstrativo. ( ) Os verbos “elimina” (linha 18), “cria” (linha 19) e “recebe” (linha 22) estão no presente do subjuntivo, indicando uma hipótese ou desejo do autor. ( ) No trecho: “[...] ofertas agressivas, renovações sucessivas [...]” (linha 19), os adjetivos destacados estão flexionados no feminino plural para concordar com os substantivos a que se referem. ( ) No fragmento: “O desconto automático [...] elimina o risco de inadimplência” (linha 18), o verbo destacado é transitivo direto, tendo “o risco de inadimplência” como seu objeto direto. ( ) No trecho: “[...] o dinheiro da renda vai embora antes de qualquer despesa com dignidade” (linhas 23-24), a expressão destacada apresenta linguagem figurada, ou seja, uma personificação. A alternativa que contém a sequência correta, de cima para baixo, é","opcoes":["F V F F V","F F V V V","V V V F V","V F F F V","V F F F F"],"correta":1,"explicacao":"Gabarito: <strong>F F V V V</strong>.","banca":"CEFET-BA","ano":2026,"temas_relacionados":["transitividade"]},{"id":7642,"enunciado":"Do ponto de vista da análise linguística do Texto II, é CORRETO o que se afirma em:","opcoes":["“Já sei! ”é uma oração sem sujeito.","O verbo querer é transitivo indireto.","Os complementos “tudo pra você” e “nada pra mim” são objetos diretos.","“Saco” é uma interjeição típica do registro formal da linguagem.","O verbo pedir é intransitivo."],"correta":2,"explicacao":"Gabarito: <strong>Os complementos “tudo pra você” e “nada pra mim” são objetos diretos.</strong>.","banca":"CPCON","ano":2026,"temas_relacionados":["transitividade"]},{"id":7666,"enunciado":"\"Ele se especializou em infectar aranhas de alçapão e parece não causar nenhum mal para seres humanos ou outras espécies.\" Com base na regência verbal e nominal dos vocábulos presentes no trecho, identifique a alternativa CORRETA.","opcoes":["O verbo 'especializar' atua como verbo transitivo indireto, com complemento preposicionado.","O verbo 'especializar' atua como intransitivo seguido de adjunto adverbial.","A preposição 'para' ocorre na expressão \"para seres humanos\" devido a regência do adjetivo 'mal' que exige complemento preposicionado.","O verbo 'causar' atua como bitransitivo, assim como na frase \"A modelo estava tão deslumbrante que causou na festa ontem\"."],"correta":0,"explicacao":"Gabarito: <strong>O verbo 'especializar' atua como verbo transitivo indireto, com complemento preposicionado.</strong>.","banca":"IDCAP","ano":2026,"temas_relacionados":["transitividade"]},{"id":7877,"enunciado":"Leia o trecho a seguir: E Macabéa, com medo de que o silêncio já significasse uma ruptura, disse ao recém-namorado: – Eu gosto tanto de parafuso e prego, e o senhor? (Clarice Lispector, A hora da estrela, 1977) No fragmento: “E Macabéa, com medo de”, classifique “com medo de”:","opcoes":["Transitivo indireto.","Locução prepositiva.","Intransitivo.","Objeto indireto.","Objeto direto."],"correta":1,"explicacao":"Gabarito: <strong>Locução prepositiva.</strong>.","banca":"FACET Concursos","ano":2025,"temas_relacionados":["transitividade"]},{"id":8084,"enunciado":"Sobre o trecho “O cliente depositará nessas carteiras o correspondente em reais e poderá fazer transações com a versão digital da moeda.” (5º§), em relação aos aspectos gramaticais, assinale a afirmativa INCORRETA.","opcoes":["O sujeito do verbo “depositar” se classifica como simples e o seu núcleo é “cliente”.","O trecho é formado por mais de uma oração que está interligada pela conjunção “e”.","“Nessas carteiras” se classifica como objeto direto do verbo “depositar”, visto que “depositar” se trata de verbo transitivo direto.","“Poderá fazer” se trata de uma locução verbal, cujo verbo “poder” está como auxiliar do verbo “fazer” que é o verbo principal."],"correta":2,"explicacao":"Gabarito: <strong>“Nessas carteiras” se classifica como objeto direto do verbo “depositar”, visto que “depositar” se trata de verbo transitivo direto.</strong>.","banca":"Instituto Consulplan","ano":2023,"temas_relacionados":["transitividade"]},{"id":8152,"enunciado":"\"Em junho, a Anistia Internacional se manifestou mais um vez contra a proibição imposta às mulheres muçulmanas de usarem o véu nos Jogos Olímpicos e Paralímpicos.\" Em relação à análise sintática do trecho, marque (V) para verdadeiro e (F) para falso nas afirmativas abaixo: (__) O trecho é formado por período composto. (__) O sujeito da forma verbal \"manifestou\" é indeterminado. (__) O verbo \"usar\" é transitivo direto e indireto sendo objeto direto \"o véu\" e objeto indireto \"jogos olímpicos e Paralímpicos\". (__) \"Em junho\" tem valor de adjunto adverbial de tempo. (__) A conjunção \"e\" é aditiva e liga a segunda oração à primeira. A sequência CORRETA de preenchimento dos parênteses é:","opcoes":["V, F, V, F, V.","F, F, V, F, V.","V, F, F, V, F.","V, V, V, F, F."],"correta":2,"explicacao":"Gabarito: <strong>V, F, F, V, F.</strong>.","banca":"AMEOSC","ano":2024,"temas_relacionados":["transitividade"]},{"id":872744,"enunciado":"Ainda no que se refere aos aspectos linguísticos do texto 6A1AAA, julgue o item que se segue.\n\n\n\n\nEm “disse-o quem sabia” (ℓ.4) e em “Quem não sabe deve perguntar” (ℓ. 9 e 10), o verbo saber é intransitivo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["transitividade"]},{"id":1125333,"enunciado":"No título do texto, há dois verbos funcionando como transitivos diretos: “avaliou a” e “chegou a”. Além disso, há dois verbos de ligação: “é” e “estamos”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"INSTITUTO AOCP","ano":2018,"tipo":"certo_errado","temas_relacionados":["transitividade"]},{"id":2441393,"enunciado":"Em relação ao quadrinho acima, julgue o item.\n\n\n\n\nO verbo “condenar” foi empregado como transitivo direto e indireto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["transitividade"]},{"id":2501237,"enunciado":"A respeito dos aspectos gerais do texto, julgue o item abaixo.\n\n\n\n\nA forma verbal “celebra” (linha 17) foi empregada como bitransitiva: seu objeto direto é “a questão” (linha 18); e seu objeto indireto é “da sustentabilidade” (linha 18).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["transitividade"]},{"id":2502609,"enunciado":"Acerca da tirinha, julgue o item a seguir.\n\n\n\n\n\nPor meio do contexto, compreende‑se que, no terceiro quadrinho, a oração está estruturada nesta ordem: sujeito + verbo de ligação + predicativo do sujeito.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["transitividade"]},{"id":2520003,"enunciado":"Em relação aos aspectos gerais do texto, julgue o item a seguir.\n\n\n\n\nAo contrário do que prega a norma, segundo a qual o verbo “prezar” é transitivo indireto, no texto, esse verbo é incorretamente empregado sem preposição, como se observa em “prezam a sustentabilidade” (linha 14).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["transitividade"]},{"id":3122285,"enunciado":"Com base no texto, julgue o item a seguir. \n\n\n\n\nNa fala do verme gordo, “roer” foi usado com diferentes transitividades. No final da fala, “roemos”, na linha 18, é transitivo direto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["transitividade"]}];
